	{
		parent.anim.PlayDirectional("Point" + parent.facingDirection, -1, 0.5f);
		switch (ChaosStopwatch.CheckInterval(barrageStopwatchID))
		{
		case StopwatchState.Ready:
			ShootFireball(fbList[fireSequence[counter]]);
			SoundManager.PlayAudioWithDistance("FireballCast", parent.transform.position);
			CameraController.ShakeCamera(0.3f);
			counter++;
			break;
		case StopwatchState.Done:
			base.ExecuteSkill();
			break;
		}
	}
	private Fireball CreateFireball(Vector2 givenPosition, Vector2 givenVector)
	{
