		currentFB.parentEntity = parent;
		currentFB.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currentFB.attackBox.gameObject.SetActive(value: false);
		currentFB.moveVector = givenVector;
		currentFB.moveSpeed = 0f;
		currentFB.flyTime = 1f;
		currentFB.goThroughWalls = true;
		return currentFB;
	}
	private void ShootFireball(Fireball givenFB)
	{
		if (!(givenFB == null))
		{
			givenFB.moveSpeed = fireballSpeed;
			givenFB.transform.SetParent(parent.bossObjects);
			givenFB.attackBox.gameObject.SetActive(value: true);
			givenFB.SetTimedIgnoreWalls(0.125f);
			FireExplosion.SpawnExplosion(givenFB.transform.position);
		}
	}
