	}

	public override void InitalizeAttack()
	{
		base.InitalizeAttack();
		delayProjCount = projectileCount;
		delayVector = targetVector;
		spawnRange = 1.5f;
	}

	public override bool CreateAllProjectiles()
	{
		if (!parent.CanUseSkills)
		{
			return base.CreateAllProjectiles();
		}
		switch (ChaosStopwatch.CheckInterval(castStopwatchID))
		{
		case StopwatchState.Running:
			return false;
		case StopwatchState.Ready:
			projectileList.Add(CreateProjectile(Globals.GetRotatedCircleVector(totalPositionCount, positionCount % totalPositionCount, delayVector)));
			positionCount++;
			return false;
		case StopwatchState.Done:
			if (currentWaveCount < extraWaveCount)
			{
				currentWaveCount++;
				delayProjCount = Mathf.Max(1, (int)((float)delayProjCount * 0.5f));
				flip = delayProjCount % 2 == 0;
				delayVector = ((!flip) ? targetVector : (-targetVector));
				castStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, castTime / (float)delayProjCount, delayProjCount);
				positionCount = totalPositionCount - (int)((float)delayProjCount * 0.5f) + (flip ? Mathf.CeilToInt((float)totalPositionCount * 0.5f) : 0);
				spawnRange += 0.75f;
				return false;
			}
			return true;
		default:
			return true;
		}
	}
