			currentWB.transform.position = spawnPosition + spawnOffset;
			currentWB.clockwise = parent.isFacingRight;
			currentWB.isUltimate = isUltimate;
			currentWB.attackBox.SetAttackInfo(parent.skillCategory, skillID, attackLevel, isUltimate);
			currentWB.followTrans = spawnTransform;
			currentWB.windupTime = windupTime;
			currentWB.moveSpeed = moveSpeed;
			currentWB.RecycleProjectile();
			WaterBarrage waterBarrage = currentWB;
			waterBarrage.ultResetEventHandlers = (WaterBarrage.UltResetEventHandlers)Delegate.Remove(waterBarrage.ultResetEventHandlers, new WaterBarrage.UltResetEventHandlers(CreateUltBurst));
			if (isUltimate)
			{
				WaterBarrage waterBarrage2 = currentWB;
