	private void CreateUltBurst(Vector2 givenPosition)
	{
		ultSpawnSeed = UnityEngine.Random.Range(0, ultSpawnCount);
		for (int i = 0; i < ultSpawnCount; i++)
		{
			ultVector = Globals.GetCirclePositionVector(ultSpawnCount, ultSpawnSeed + i);
			currentIS = parent.GetBossPoolItem<IceShard>();
			if (currentIS == null || currentIS.transform == null)
			{
				break;
			}
			currentIS.transform.position = givenPosition;
			currentIS.attackBox.SetAttackInfo(parent.skillCategory, skillID, attackLevel, isUltimate);
			currentIS.attackBox.knockbackOverwriteVector = ultVector;
			currentIS.RecycleProjectile();
			currentIS.PointIceShard(ultVector);
			currentIS.ReleaseIceShard(ultVector);
		}
		parent.anim.Play("DoubleCast", -1, 0.67f);
		SoundManager.PlayAudioWithDistance("WaterArcBasic", parent.transform.position);
		base.ExecuteSkill();
	}

	private void CreateWaterBombs()
	{
		wbList.Clear();
		spawnPosition = parent.transform.position;
		for (int i = 0; i < spawnCount; i++)
		{
			currentWB = ChaosInst<WaterBomb>(WaterBomb.Prefab);
			currentWB.initiateOnStart = false;
			currentWB.attack.SetAttackInfo(parent.skillCategory, skillID);
			currentWB.baseFlightTime = throwTime;
			currentWB.movement.InitOrbitAngle(Globals.GetCirclePositionVector(spawnCount, i));
			wbList.Add(currentWB);
		}
	}

	private void ThrowWaterBombs()
	{
		spawnPosition = ((parent.UpdateTargetInfo() != null) ? parent.closestTargetInfo.position : parent.transform.position);
		positionSeed = UnityEngine.Random.Range(0, positionOffset);
		for (int i = 0; i < spawnCount; i++)
		{
			if (!(wbList[i] == null))
			{
				currentWB = wbList[i];
				currentWB.targetPosition = spawnPosition + Globals.GetCirclePositionVector(positionCount, i * positionOffset + positionSeed) * orbitRadius;
				currentWB.InitThrow();
			}
		}
	}
