    n = re.search(r'^(?:- id: |\S)', text[m.end():], re.M)
    end = m.end() + (n.start() if n else len(text) - m.end())
    return m.start(), end

def check_safe(new):
    if "'" in new or ': ' in new or ' #' in new:
        raise Exception('unsafe new text: ' + new)

